        /// <summary>
        /// 判断热更文件是否存在
        /// </summary>
        /// <param name="bundleName"></param>
        public bool HotAssetsIsExists(string bundleName)
        {
            foreach (var item in mAllHotAssetList)
            {
                if (string.Equals(bundleName, item.abName))
                    return true;
            }
            return false;
        }


