            GUIContent addContent = EditorGUIUtility.IconContent("CollabCreate Icon".Trim(), "");
            if (GUILayout.Button(addContent, GUILayout.Width(130), GUILayout.Height(170)))
            {
                BundleModuleConfig.ShowWindow("");
