        /// <summary>
        /// 所有资源下载完成
        /// </summary>
        public void DownLoadAssetBundleFinish()
        {
            if (File.Exists(mLocalHotAssetManisetPath))
                File.Delete(mLocalHotAssetManisetPath);
            //将服务端热更清单文件拷贝到本地
            File.Copy(mServerHotAssetsManifestPath, mLocalHotAssetManisetPath);
            //设置为下载完成
